1	// Dependency-free browser sound activity detection (SAD), not speech classification.
2	// Signals are measured on a microphone stream the user explicitly granted.
3	export class AdaptiveSoundGate {
4	  constructor({sampleRate, sensitivityDb = 12, onClip = () => {}, onState = () => {}}) {
5	    this.rate = sampleRate;
6	    this.sensitivityDb = sensitivityDb;
7	    this.onClip = onClip;
8	    this.onState = onState;
9	    this.samplesSeen = 0;
10	    this.calibrationEnd = sampleRate * 1.4;
11	    this.noiseDb = -65;
12	    this.calibrationCount = 0;
13	    this.history = [];
14	    this.active = false;
15	    this.frames = [];
16	    this.startedAt = 0;
17	    this.pendingAbove = 0;
18	    this.silentSamples = 0;
19	    this.lastStatus = '';
20	    this.stats = {levelDb: -100, noiseDb: -65, thresholdDb: -53, elapsed: 0};
21	    this.preSamples = Math.round(sampleRate * 0.35);
22	    this.triggerSamples = Math.round(sampleRate * 0.18);
23	    this.hangSamples = Math.round(sampleRate * 0.8);
24	    this.maxSamples = Math.round(sampleRate * 22);
25	  }
26	  emitState(kind) {
27	    if (kind !== this.lastStatus) {
28	      this.lastStatus = kind;
29	    }
30	    this.onState(kind, {...this.stats});
31	  }
32	  threshold() {
33	    return Math.min(-12, Math.max(-56, this.noiseDb + this.sensitivityDb));
34	  }
35	  push(input) {
36	    if (!input?.length) return;
37	    const buf = input instanceof Float32Array ? input : new Float32Array(input);
38	    let power = 0;
39	    for (let i = 0; i < buf.length; i++) power += buf[i] * buf[i];
40	    const db = 20 * Math.log10(Math.sqrt(power / buf.length) + 1e-9);
41	    const begin = this.samplesSeen;
42	    this.samplesSeen += buf.length;
43	    const frame = {buf, begin};
44	    this.stats = {levelDb: +db.toFixed(1), noiseDb: +this.noiseDb.toFixed(1),
45	                  thresholdDb: +this.threshold().toFixed(1), elapsed: this.samplesSeen / this.rate};
46	    if (this.samplesSeen <= this.calibrationEnd) {
47	      this.noiseDb = this.calibrationCount ? (this.noiseDb * 0.92 + db * 0.08) : db;
48	      this.calibrationCount++;
49	      this.emitState('calibrating');
50	      return;
51	    }
52	    if (!this.active) {
53	      this.history.push(frame);
54	      while (this.history.length > 1 && this.samplesSeen - this.history[0].begin > this.preSamples) this.history.shift();
55	      const isAbove = db >= this.threshold();
56	      if (isAbove) this.pendingAbove += buf.length;
57	      else this.pendingAbove = 0;
58	      if (this.pendingAbove >= this.triggerSamples) {
59	        this.active = true;
60	        this.frames = this.history.slice();
61	        this.startedAt = this.frames[0].begin;
62	        this.history = [];
63	        this.pendingAbove = 0;
64	        this.silentSamples = 0;
65	        this.emitState('recording');
66	      } else {
67	        // Only adapt during idle, especially when the energy stays near background.
68	        if (!isAbove) this.noiseDb = 0.98 * this.noiseDb + 0.02 * db;
69	        this.emitState('silent');
70	      }
71	      return;
72	    }
73	    this.frames.push(frame);
74	    // Second lower threshold prevents rapid flickering around the trigger level.
75	    this.silentSamples = db < this.threshold() - 4 ? this.silentSamples + buf.length : 0;
76	    this.emitState('recording');
77	    if (this.silentSamples >= this.hangSamples) this.flush();
78	    else if (this.samplesSeen - this.startedAt >= this.maxSamples) this.flush(true);
79	  }
80	  flush(forceSplit = false) {
81	    if (!this.active || !this.frames.length) return;
82	    const start = this.startedAt;
83	    const size = this.frames.reduce((n, f) => n + f.buf.length, 0);
84	    // Ignore isolated, very brief transients.
85	    if (size >= this.rate * 0.35) {
86	      const samples = new Float32Array(size);
87	      let cursor = 0;
88	      for (const f of this.frames) {samples.set(f.buf, cursor); cursor += f.buf.length;}
89	      this.onClip({samples, sampleRate: this.rate, startSeconds: start / this.rate,
90	                   durationSeconds: size / this.rate});
91	    }
92	    if (forceSplit) {
93	      // Small overlap reduces syllable truncation, but may create duplicate words.
94	      const tail = [];
95	      let tailSize = 0;
96	      for (let i = this.frames.length - 1; i >= 0; i--) {
97	        tail.unshift(this.frames[i]); tailSize += this.frames[i].buf.length;
98	        if (tailSize >= this.rate * 0.25) break;
99	      }
100	      this.frames = tail;
101	      this.startedAt = tail[0]?.begin ?? this.samplesSeen;
102	      this.silentSamples = 0;
103	      this.emitState('recording');
104	    } else {
105	      this.frames = [];
106	      this.active = false;
107	      this.silentSamples = 0;
108	      this.history = [];
109	      this.emitState('silent');
110	    }
111	  }
112	  finish() {this.flush(false); this.emitState('stopped');}
113	}
