115	export function encodeWav(samples, sampleRate) {
116	  const out = new ArrayBuffer(44 + samples.length * 2);
117	  const dv = new DataView(out);
118	  const str = (offset, value) => {for(let i=0;i<value.length;i++) dv.setUint8(offset+i,value.charCodeAt(i));};
119	  str(0,'RIFF'); dv.setUint32(4,36+samples.length*2,true); str(8,'WAVE');
120	  str(12,'fmt '); dv.setUint32(16,16,true); dv.setUint16(20,1,true); dv.setUint16(22,1,true);
121	  dv.setUint32(24,sampleRate,true); dv.setUint32(28,sampleRate*2,true);
122	  dv.setUint16(32,2,true); dv.setUint16(34,16,true);
123	  str(36,'data'); dv.setUint32(40,samples.length*2,true);
124	  for (let i=0;i<samples.length;i++) {
125	    const s = Math.max(-1,Math.min(1,samples[i]));
126	    dv.setInt16(44+i*2,Math.round(s<0?s*32768:s*32767),true);
127	  }
128	  return new Blob([out],{type:'audio/wav'});
129	}
