1	import {AdaptiveSoundGate, encodeWav} from './sound-gate.js';
2	const $=s=>document.getElementById(s);
3	const headers={'X-Local-Whisper-Client':'1'};
4	const states={uploading:'上传中',queued:'排队中',running:'转写中',complete:'完成',failed:'失败',interrupted:'中断'};
5	const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
6	const fmt=t=>{const x=Math.max(0,Math.floor(Number(t)||0));return `${String(Math.floor(x/60)).padStart(2,'0')}:${String(x%60).padStart(2,'0')}`;};
7	function tab(name){document.querySelectorAll('.tab').forEach(e=>e.classList.toggle('active',e.dataset.tab===name));document.querySelectorAll('.mode').forEach(e=>e.classList.toggle('hidden',e.id!==`pane-${name}`));}
8	document.querySelectorAll('.tab').forEach(e=>e.addEventListener('click',()=>tab(e.dataset.tab)));
9	async function request(url,options={}) {const response=await fetch(url, options); const body=await response.json(); if(!response.ok)throw Error(typeof body.detail==='string'?body.detail:`HTTP ${response.status}`);return body;}
10	let picked=null;
11	function selectFile(f){picked=f; $('picked').textContent=f?`${f.name} · ${(f.size/1048576).toFixed(1)} MB`:'MP3 · WAV · M4A · MP4 · FLAC · WEBM 等';}
12	$('drop').onclick=()=>$('file').click();
13	$('drop').onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();$('file').click();}};
14	$('file').onchange=e=>selectFile(e.target.files[0]||null);
15	for(const name of ['dragover','drop']) $('drop').addEventListener(name,e=>e.preventDefault());
16	$('drop').addEventListener('drop',e=>selectFile(e.dataTransfer.files[0]||null));
17	$('upload-send').onclick=async()=>{
18	  if(!picked){$('upload-message').textContent='请先选择文件';return;}
19	  const fd=new FormData(); fd.append('file',picked);fd.append('model',$('upload-model').value);fd.append('language',$('upload-lang').value);fd.append('task','transcribe');
20	  $('upload-send').disabled=true; $('upload-message').textContent='上传中…';
21	  try{const j=await request('/api/transcribe',{method:'POST',headers,body:fd});$('upload-message').textContent='任务已排队：'+j.id.slice(0,8);selectFile(null);$('file').value='';await refreshJobs();}
22	  catch(e){$('upload-message').textContent='提交失败：'+e.message;}
23	  finally{$('upload-send').disabled=false;}
24	};
25	function batchRequest(){return {input_directory:$('batch-input').value.trim(),output_directory:$('batch-output').value.trim()||null,recursive:$('batch-recursive').checked,skip_existing:$('batch-skip').checked,model:$('batch-model').value,language:$('batch-lang').value};}
26	$('batch-preview').onclick=async()=>{
27	  $('batch-info').textContent='正在检查路径…';
28	  try{const d=await request('/api/batch/preview',{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(batchRequest())});
29	  $('batch-info').textContent=`找到 ${d.count} 个 MP3\n`+d.files.join('\n')+(d.count>40?'\n…仅展示前 40 个':'');}
30	  catch(e){$('batch-info').textContent='扫描失败：'+e.message;}
31	};
32	$('batch-start').onclick=async()=>{
33	  $('batch-start').disabled=true;
34	  try{const d=await request('/api/batch',{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(batchRequest())});
35	  $('batch-info').textContent=`已提交 ${d.total_files} 个 MP3，正在按顺序处理。\nSRT 输出位置：${d.output_directory}\n批量任务：${d.id.slice(0,8)}`;await refreshJobs();}
36	  catch(e){$('batch-info').textContent='提交失败：'+e.message;}
37	  finally{$('batch-start').disabled=false;}
38	};
39	async function refreshJobs(){
40	  try{const d=await request('/api/jobs');const root=$('jobs');if(!d.length){root.innerHTML='<div class="empty">暂无任务</div>';return;}
41	  root.innerHTML=d.slice(0,25).map(j=>{
42	    const suffix=j.kind==='batch'?` · 已完成 ${j.completed_files||0}/${j.total_files||0} · 跳过 ${j.skipped_files||0} · 失败 ${j.failed_files||0}`:'';
43	    const downloads=j.status==='complete'&&(!j.kind||j.kind==='upload')?`<div class="downloads">${['txt','srt','vtt','json'].map(f=>`<a href="/api/jobs/${encodeURIComponent(j.id)}/download/${f}">${f.toUpperCase()}</a>`).join('')}</div>`:'';
44	    const preview=j.text?`<div class="preview">${escapeHTML(j.text.slice(0,1000))}</div>`:'';
45	    const errors=j.errors?.length?`<div class="error">失败样例：${escapeHTML(j.errors.slice(0,3).map(x=>x.file+': '+x.error).join(' | '))}</div>`:'';
46	    return `<div class="job"><div class="jobhead"><b class="jobname">${escapeHTML(j.name)}</b><span class="pill ${escapeHTML(j.status)}">${states[j.status]||escapeHTML(j.status)}</span></div><div class="stage">${escapeHTML(j.stage||'')} ${escapeHTML(suffix)} ${j.error?`<span class="error">${escapeHTML(j.error)}</span>`:''}</div>${preview}${downloads}${errors}</div>`;
47	  }).join('');
48	  }catch(e){/* leave prior status visible */}
49	}
