51	let liveSession=null, micStream=null, micContext=null, micSource=null, micNode=null, gate=null;
52	let monitoring=false, sending=false, stopping=false, pending=[], dropped=0;
53	function micState(state,stats){
54	  $('mic-orb').className=`orb ${state==='recording'?'recording':state==='calibrating'?'calibrating':'silent'}`;
55	  $('mic-glyph').textContent=state==='recording'?'●':'◌';
56	  $('live-state').textContent={calibrating:'校准环境底噪…',silent:'静止待机 · 检测中',recording:'检测到声音 · 采集中',stopped:'监听已停止'}[state]||'等待开始';
57	  $('live-note').textContent=state==='recording'?'正在本机录制这段声音':'未检测到明显声音时，不提交推理任务';
58	  $('meter-fill').style.width=`${Math.max(0,Math.min(100,(stats.levelDb+80)/70*100))}%`;
59	  $('meter-label').textContent=`当前 ${stats.levelDb} dBFS · 触发阈值 ${stats.thresholdDb} dBFS · 背景 ${stats.noiseDb} dBFS`;
60	  $('elapsed').textContent=fmt(stats.elapsed);
61	}
62	function liveClip(clip){
63	  if(pending.length>=12){dropped++;$('live-message').textContent=`CPU 转写速度落后，已有 ${dropped} 段未提交；建议改用 tiny 或稍后上传完整录音。`;return;}
64	  pending.push({...clip,blob:encodeWav(clip.samples,clip.sampleRate)});
65	  $('live-message').textContent=`采集 ${clip.startSeconds.toFixed(1)}–${(clip.startSeconds+clip.durationSeconds).toFixed(1)}s · 本地等待上传 ${pending.length} 段`;
66	  drain();
67	}
68	async function drain(){
69	  if(sending||!liveSession)return;
70	  sending=true;
71	  try{
72	    while(pending.length){
73	      const c=pending[0];const fd=new FormData();fd.append('file',c.blob,'mic.wav');fd.append('offset_seconds',String(c.startSeconds));fd.append('duration_seconds',String(c.durationSeconds));
74	      try{
75	        await request(`/api/live/${liveSession}/chunks`,{method:'POST',headers,body:fd});
76	        pending.shift();
77	      }catch(e){
78	        if(String(e.message).includes('队列已满')) {await new Promise(r=>setTimeout(r,2500));continue;}
79	        pending.shift();dropped++;
80	        $('live-message').textContent=`音频片段提交失败：${e.message}，丢失段数 ${dropped}`;
81	      }
82	    }
83	  }finally{sending=false;if(stopping){
84	    try{await request(`/api/live/${liveSession}/stop`,{method:'POST',headers});}catch(e){}
85	    stopping=false;$('mic-btn').disabled=false;
86	  }}
87	}
88	async function beginMic(){
89	  if(!navigator.mediaDevices?.getUserMedia||!window.AudioWorkletNode) throw Error('浏览器不支持安全上下文中的 AudioWorklet 麦克风录制。请使用最新版 Chrome / Firefox 的 localhost 页面。');
90	  micStream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true,autoGainControl:false},video:false});
91	  try{
92	    const s=await request('/api/live/sessions',{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({model:$('live-model').value,language:$('live-lang').value})});
93	    liveSession=s.id;
94	    micContext=new AudioContext({latencyHint:'interactive'});
95	    await micContext.audioWorklet.addModule('/assets/recorder-worklet.js');
96	    micSource=micContext.createMediaStreamSource(micStream);
97	    micNode=new AudioWorkletNode(micContext,'mic-frames');
98	    gate=new AdaptiveSoundGate({sampleRate:micContext.sampleRate,sensitivityDb:+$('sensitivity').value,onClip:liveClip,onState:micState});
99	    micNode.port.onmessage=e=>gate?.push(e.data);
100	    micSource.connect(micNode);micNode.connect(micContext.destination);
101	    await micContext.resume();
102	    monitoring=true;pending=[];dropped=0;
103	    $('mic-btn').textContent='停止监听并生成字幕';
104	    $('live-model').disabled=true;$('live-lang').disabled=true;
105	    $('live-message').textContent='已请求麦克风权限。仅在检测到声音时发送录音片段给本机 Whisper。';
106	  }catch(e){micStream?.getTracks().forEach(t=>t.stop()); micStream=null; if(micContext)await micContext.close().catch(()=>{});micContext=null;throw e;}
107	}
108	async function endMic(){
109	  monitoring=false;stopping=true;
110	  micNode?.port.close();if(gate){gate.finish();gate=null;}
111	  micStream?.getTracks().forEach(t=>t.stop());micStream=null;
112	  if(micContext)await micContext.close().catch(()=>{});
113	  micContext=null;micSource=null;micNode=null;
114	  $('mic-btn').disabled=true;$('mic-btn').textContent='正在提交剩余录音…';
115	  $('live-model').disabled=false;$('live-lang').disabled=false;
116	  $('live-message').textContent=`麦克风已停止。剩余待提交：${pending.length} 段，后台转写仍可能继续。`;
117	  await drain();
118	  $('mic-btn').textContent='开始新的监听';
119	  $('live-state').textContent='已停止，麦克风已关闭';
120	}
121	$('mic-btn').onclick=async()=>{
122	  $('mic-btn').disabled=true;
123	  try{if(monitoring)await endMic();else await beginMic();}
124	  catch(e){$('live-message').textContent='麦克风启动失败：'+e.message;}
125	  finally{if(!stopping)$('mic-btn').disabled=false;}
126	};
127	$('sensitivity').oninput=()=>{const x=+$('sensitivity').value;if(gate)gate.sensitivityDb=x;$('sensitivity-label').textContent=`高于背景 ${x} dB（数值越小越灵敏）`;};
128	async function refreshLive(){
129	  if(!liveSession)return;
130	  try{
131	    const d=await request(`/api/live/${liveSession}`);
132	    const timeline=$('live-transcript');
133	    timeline.innerHTML=d.segments?.length?d.segments.slice(-80).map(s=>`<p><time>${fmt(s.start)}</time>${escapeHTML(s.text)}</p>`).join(''):'<span class="muted">尚无转写内容。声音片段会排队由 CPU 处理。</span>';
134	    $('live-downloads').innerHTML=`${['srt','txt','vtt','json'].map(f=>`<a href="/api/live/${encodeURIComponent(liveSession)}/download/${f}">保存完整 ${f.toUpperCase()}</a>`).join('')}`;
135	    if(d.failed)$('live-message').textContent=`已转写 ${d.completed}/${d.submitted} 段，失败 ${d.failed} 段：${d.last_error||''}`;
136	  }catch(e){}
137	}
138	async function tick(){try{const h=await request('/api/health');$('health').textContent=`本地运行 · ${h.threads} CPU 线程`;$('health').classList.add('ok');}catch(e){$('health').textContent='服务断开';$('health').classList.remove('ok');}await Promise.all([refreshJobs(),refreshLive()]);}
139	window.addEventListener('pagehide',()=>{micStream?.getTracks().forEach(t=>t.stop());});
140	tick();setInterval(tick,2600);
