1	// Worklet has no network access and always outputs zero to prevent feedback.
2	class MicFrames extends AudioWorkletProcessor {
3	  constructor() {super(); this.buffer=new Float32Array(1024); this.used=0;}
4	  process(inputs, outputs) {
5	    const channel=inputs[0]?.[0];
6	    if (channel) {
7	      for (let i=0;i<channel.length;i++) {
8	        this.buffer[this.used++]=channel[i];
9	        if (this.used===1024) {
10	          const frame=this.buffer;
11	          this.port.postMessage(frame,[frame.buffer]);
12	          this.buffer=new Float32Array(1024); this.used=0;
13	        }
14	      }
15	    }
16	    const output=outputs[0];
17	    if (output) for(const ch of output) ch.fill(0);
18	    return true;
19	  }
20	}
21	registerProcessor('mic-frames',MicFrames);
